        return image_patch

    glasses.sort(key=lambda g: g.horizontal_center + g.vertical_center / 2)
    plates.sort(key=lambda p: p.horizontal_center + p.vertical_center / 2)

    left_plate = plates[0]
    right_plate = plates[-1]

    if glasses[0].horizontal_center < left_plate.horizontal_center:
        return glasses[0]
    elif glasses[0].horizontal_center > right_plate.horizontal_center:
        return glasses[0]
    else:
        return glasses[0]

